import numpy as np
from scipy.optimize import least_squares
eps=df['eps'].values; T=df['T'].values; s=df['sigma'].values
def nmse(p,y): return np.mean((p-y)**2)/np.var(y)
def f1(P): return P[0]+P[1]*np.exp(-P[2]/T)*eps**P[3]+P[4]*np.exp(-P[5]*eps)+P[6]*T**P[7]
def f2(P): return P[0]+P[1]*T**P[2]*(1-np.exp(-P[3]*eps))+P[4]*eps**P[5]*np.exp(-P[6]/T)
def f3(P): return P[0]+P[1]*eps**P[2]*T**P[3]+P[4]*np.exp(-P[5]*eps)*T**P[6]+P[7]*np.exp(-P[8]/T)
def f4(P): return P[0]+P[1]*T**P[2]*np.exp(-P[3]*eps)+P[4]*eps**P[5]+P[6]/eps
out=[]
