for name,f,n in [('f1',f1,8),('f2',f2,7),('f3',f3,9),('f4',f4,7)]:
    best=None
    for trial in range(25):
        P0=rng.uniform(-2,2,n)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda P: np.nan_to_num(f(P)-s,nan=1e6,posinf=1e6,neginf=-1e6), P0, max_nfev=500)
